S = json.load(open(CK / "simulasyon.json")); SP = json.load(open(CK / "simulasyon_p.json"))


def _yayilim():
    """NB2'nin ortak alpha varsayımı: ülke bazında moment tahmini ve log varyans ~ log ortalama eğimi (Model 1, NB)."""
    import numpy as np, pandas as pd
    from tezlib import load, sample, fit_nb, CTRL5, PH, TR
    est = sample(load()); r = fit_nb(est, PH + ["lnK1"] + CTRL5, cluster=None); mu = r.extra["mu"]; y = est.ccm.values
    a = pd.Series(((y - mu) ** 2 - mu) / mu ** 2).groupby(est.country.values).mean()
    return {TR[k]: float(v) for k, v in a.items()}, float(np.polyfit(np.log(mu), np.log((y - mu) ** 2 + 0.5), 1)[0])


ALFA_I, VAR_EGIM = _yayilim()
SEN = ["A", "A2", "B", "C"]


def tr(x, d=3):
    if x is None: return "–"
    s = f"{x:,.{d}f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return s.replace("-", "−")


def pv(p):
    return "<0,001" if p < 0.0005 else tr(p, 3)


def pct(b): return tr(100 * (2.718281828459045 ** b - 1), 1)


mcp = lambda fam, j: [SP[g][fam]["p_tek"][j] for g in SEN]          # tek yönlü Monte Carlo p, dört senaryo
mcr = lambda fam, j: pv(min(mcp(fam, j))) if pv(min(mcp(fam, j))) == pv(max(mcp(fam, j))) else f"{pv(min(mcp(fam, j)))}–{pv(max(mcp(fam, j)))}"
simrg = lambda key, g: f"%{tr(100 * min(min(S[g][f][key]) for f in ('poisson', 'nb')), 0)}–{tr(100 * max(max(S[g][f][key]) for f in ('poisson', 'nb')), 0)}"


c = lambda m, fam, k, f="b": R[m][fam]["coef"][k][f]
bo = lambda m, fam, k, f="se": R[m][fam]["boot"]["coef"][k][f]
pt13 = lambda b_, se: float(2 * tdist.sf(abs(b_ / se), 13))
ek = lambda nm, fam, k, f="b": R["ek"][nm][fam][k][f]
M1, M2, EK, SG = R["m1"], R["m2"], R["ek"], R["saglamlik"]
P, N = "poisson", "nb"
yb = E["yil_boot"]; pl = E["plasebo"]; vif2 = E["vif_m2"]; ik = E["ici_kor"]; eg = E["egilim_katkisi"]
loo = R["loo"]
loo_p5 = sum(1 for v in loo.values() if v["hesap"][0][1] < 0.05)
ici = {(x["a"], x["b"]): x["ici"] for x in R["tanim"]["t54"]}
f1_z0 = bo("m1", P, "F1", "z0")
bc_levels = (norm.cdf(2 * f1_z0 - 1.96) * 100, norm.cdf(2 * f1_z0 + 1.96) * 100)


def F(id, onem, kat, baslik, yer, kaynak, durum, tespit, kanit, oneri):
    return dict(id=id, onem=onem, kat=kat, baslik=baslik, yer=yer, kaynak=kaynak, durum=durum, tespit=tespit, kanit=kanit, oneri=oneri)


